"use client"

import { useState, useEffect } from "react"
import { ChevronLeft, Calendar, Eye, Share2, Bookmark } from "lucide-react"
import Link from "next/link"

interface NewsArticle {
  id: string
  title: string
  excerpt: string
  content: string
  category: string
  image?: string
  publishedAt: string
  views: number
  author: string
}

export default function NewsPage() {
  const [news, setNews] = useState<NewsArticle[]>([])
  const [selectedCategory, setSelectedCategory] = useState("all")
  const [loading, setLoading] = useState(true)

  const categories = [
    { value: "all", label: "All News" },
    { value: "announcements", label: "Announcements" },
    { value: "events", label: "Events" },
    { value: "projects", label: "Projects" },
    { value: "health", label: "Health" },
  ]

  useEffect(() => {
    const fetchNews = async () => {
      try {
        const response = await fetch("/api/news")
        const data = await response.json()
        setNews(data.news || [])
      } catch (error) {
        console.error("[v0] Error fetching news:", error)
      } finally {
        setLoading(false)
      }
    }

    fetchNews()
  }, [])

  const filteredNews =
    selectedCategory === "all" ? news : news.filter((article) => article.category === selectedCategory)

  return (
    <div className="flex flex-col min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-orange-600 text-white px-4 py-4">
        <div className="flex items-center gap-3 mb-2">
          <Link href="/">
            <ChevronLeft className="w-6 h-6" />
          </Link>
          <h1 className="text-xl font-bold">City News</h1>
        </div>
        <p className="text-orange-100 text-sm">Latest updates from Calapan City</p>
      </header>

      {/* Category Filter */}
      <div className="bg-white border-b border-gray-200 px-4 py-3 overflow-x-auto">
        <div className="flex gap-2">
          {categories.map((category) => (
            <button
              key={category.value}
              onClick={() => setSelectedCategory(category.value)}
              className={`px-4 py-2 rounded-lg font-semibold text-sm whitespace-nowrap transition-colors ${
                selectedCategory === category.value
                  ? "bg-orange-600 text-white"
                  : "bg-gray-100 text-gray-600 hover:bg-gray-200"
              }`}
            >
              {category.label}
            </button>
          ))}
        </div>
      </div>

      {/* Main Content */}
      <main className="flex-1 px-4 py-4 overflow-y-auto pb-20">
        {loading ? (
          <div className="flex items-center justify-center py-12">
            <div className="text-center">
              <div className="w-12 h-12 border-4 border-orange-600 border-t-transparent rounded-full animate-spin mx-auto mb-4" />
              <p className="text-gray-600">Loading news...</p>
            </div>
          </div>
        ) : filteredNews.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12">
            <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mb-4">
              <Calendar className="w-10 h-10 text-gray-400" />
            </div>
            <h3 className="text-lg font-semibold text-gray-900 mb-2">No news articles</h3>
            <p className="text-gray-600 text-center max-w-sm">Check back later for updates from the city.</p>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredNews.map((article) => (
              <Link
                key={article.id}
                href={`/news/${article.id}`}
                className="block bg-white rounded-xl overflow-hidden shadow-sm border border-gray-100 hover:shadow-md transition-shadow"
              >
                {article.image && (
                  <div className="aspect-video bg-gray-200 overflow-hidden">
                    <img
                      src={article.image || "/placeholder.svg"}
                      alt={article.title}
                      className="w-full h-full object-cover"
                    />
                  </div>
                )}

                <div className="p-4">
                  <div className="flex items-center gap-2 mb-2">
                    <span className="px-2 py-1 bg-orange-100 text-orange-700 text-xs font-semibold rounded">
                      {article.category}
                    </span>
                    <span className="text-xs text-gray-500 flex items-center gap-1">
                      <Calendar className="w-3 h-3" />
                      {article.publishedAt}
                    </span>
                  </div>

                  <h3 className="font-bold text-gray-900 mb-2 text-lg leading-tight">{article.title}</h3>
                  <p className="text-sm text-gray-600 mb-3 leading-relaxed line-clamp-2">{article.excerpt}</p>

                  <div className="flex items-center justify-between text-xs text-gray-500">
                    <span>By {article.author}</span>
                    <div className="flex items-center gap-3">
                      <span className="flex items-center gap-1">
                        <Eye className="w-3 h-3" />
                        {article.views}
                      </span>
                      <button
                        onClick={(e) => {
                          e.preventDefault()
                          // Share functionality
                        }}
                        className="flex items-center gap-1 hover:text-orange-600"
                      >
                        <Share2 className="w-3 h-3" />
                      </button>
                      <button
                        onClick={(e) => {
                          e.preventDefault()
                          // Bookmark functionality
                        }}
                        className="flex items-center gap-1 hover:text-orange-600"
                      >
                        <Bookmark className="w-3 h-3" />
                      </button>
                    </div>
                  </div>
                </div>
              </Link>
            ))}
          </div>
        )}
      </main>
    </div>
  )
}
